"""Resource registry for code generated by protoc-gen-mcp.

Ports of mcpruntime.ExtractURIParams and mcpruntime.MarshalResourceContent
keep template matching and content encoding identical to the Go target.
"""

from __future__ import annotations

import json
import re
import urllib.parse
import weakref
from dataclasses import dataclass
from typing import Any

import mcp.server.lowlevel
import mcp.server.lowlevel.helper_types
import mcp.shared.exceptions
import mcp.types

from ._util import maybe_await, message_to_json


@dataclass(frozen=True)
class RegisteredResource:
    resource: mcp.types.Resource
    reader: Any


@dataclass(frozen=True)
class RegisteredResourceTemplate:
    template: mcp.types.ResourceTemplate
    pattern: Any
    names: tuple[str, ...]
    lister: Any
    reader: Any


class ResourceRegistry:
    """Resources registered on one low-level server, shared by every generated module."""

    def __init__(self) -> None:
        self.static: dict[str, RegisteredResource] = {}
        self.templates: list[RegisteredResourceTemplate] = []

    def add_static(self, entry: RegisteredResource) -> None:
        uri = str(entry.resource.uri)
        if uri in self.static:
            raise ValueError(f"duplicate resource registration: {uri}")
        self.static[uri] = entry

    def add_template(self, entry: RegisteredResourceTemplate) -> None:
        for existing in self.templates:
            if existing.template.uriTemplate == entry.template.uriTemplate:
                raise ValueError(f"duplicate resource template registration: {entry.template.uriTemplate}")
        self.templates.append(entry)


_REGISTRIES: weakref.WeakKeyDictionary[mcp.server.lowlevel.Server, ResourceRegistry] = weakref.WeakKeyDictionary()
_URI_TEMPLATE_PARAM = re.compile(r"\{([a-zA-Z_][a-zA-Z0-9_]*)\}")
_MALFORMED_PERCENT_ESCAPE = re.compile(r"%(?![0-9A-Fa-f]{2})")


def resource_error(message: str, uri: str) -> mcp.shared.exceptions.McpError:
    return mcp.shared.exceptions.McpError(
        mcp.types.ErrorData(code=mcp.types.INVALID_PARAMS, message=message, data={"uri": uri})
    )


def resource_listing(model: Any, descriptor_json: str, namespace: str | None, name: str) -> Any:
    """Builds a Resource or ResourceTemplate from its generated descriptor."""
    descriptor = json.loads(descriptor_json)
    descriptor["name"] = name if not namespace else f"{namespace}_{name}"
    return model.model_validate(descriptor)


def compile_uri_template(uri_template: str) -> Any:
    parts = _URI_TEMPLATE_PARAM.split(uri_template)
    pattern = "".join(re.escape(part) if index % 2 == 0 else "([^/]+)" for index, part in enumerate(parts))
    return re.compile(pattern)


def match_uri_template(entry: RegisteredResourceTemplate, uri: str) -> dict[str, str] | None:
    """Returns percent-decoded template parameters, or None when uri does not match."""
    match = entry.pattern.fullmatch(uri)
    if match is None:
        return None
    params: dict[str, str] = {}
    for name, raw in zip(entry.names, match.groups()):
        if _MALFORMED_PERCENT_ESCAPE.search(raw):
            raise resource_error(f"mcpruntime: parameter {name!r} in uri {uri!r} has a malformed percent escape", uri)
        try:
            value = urllib.parse.unquote(raw, errors="strict")
        except UnicodeDecodeError as error:
            raise resource_error(f"mcpruntime: parameter {name!r} in uri {uri!r}: {error}", uri) from error
        if value == "":
            raise resource_error(f"mcpruntime: parameter {name!r} has empty value in uri {uri!r}", uri)
        params[name] = value
    return params


async def read_resource_contents(
    result: Any,
    uri: str,
    *,
    mime_type: str,
    kind: str,
    content_field: str | None,
    to_pb: Any,
    meta: dict[str, Any] | None,
) -> Any:
    """Encodes a handler result: ProtoJSON, a string/bytes field, or raw str/bytes."""
    value = await maybe_await(result)
    if value is None:
        raise RuntimeError(f"mcpruntime: resource {uri!r} handler returned None")
    if kind == "raw":
        if not isinstance(value, (str, bytes)):
            raise RuntimeError(f"mcpruntime: resource {uri!r} handler must return str or bytes, got {type(value).__name__}")
        content: str | bytes = value
    else:
        message = to_pb(value)
        if kind == "protojson":
            payload = json.loads(message_to_json(message))
            content = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
        elif kind == "text_field":
            content = str(getattr(message, content_field))
        else:
            content = bytes(getattr(message, content_field))
    return mcp.server.lowlevel.helper_types.ReadResourceContents(content=content, mime_type=mime_type, meta=meta)


def install_resource_registry(server: mcp.server.lowlevel.Server) -> ResourceRegistry:
    """Returns the server's resource registry, installing the SDK resource handlers once."""
    registry = _REGISTRIES.get(server)
    if registry is not None:
        return registry
    registry = ResourceRegistry()
    _REGISTRIES[server] = registry

    @server.list_resources()
    async def _list_resources() -> list[mcp.types.Resource]:
        resources = [entry.resource for entry in registry.static.values()]
        for entry in registry.templates:
            resources.extend(await maybe_await(entry.lister()))
        return resources

    @server.list_resource_templates()
    async def _list_resource_templates() -> list[mcp.types.ResourceTemplate]:
        return [entry.template for entry in registry.templates]

    @server.read_resource()
    async def _read_resource(uri: Any) -> list[Any]:
        raw_uri = str(uri)
        entry = registry.static.get(raw_uri)
        if entry is not None:
            return [await entry.reader(raw_uri, {})]
        for template in registry.templates:
            params = match_uri_template(template, raw_uri)
            if params is not None:
                return [await template.reader(raw_uri, params)]
        raise resource_error("Resource not found", raw_uri)

    return registry
